const j = $json || {};
const mode = j.mode || "generate_background_and_render_text";
const validModes = ["existing_drive_image", "generate_background_and_render_text", "render_from_template"];
if (!validModes.includes(mode)) {
  return {
    ok: false,
    errorCode: "INVALID_MODE",
    errorMessage: "Mode must be one of: " + validModes.join(", ")
  };
}
return {
  jobId: j.jobId || null,
  mode,
  headline: j.headline || "",
  subheadline: j.subheadline || "",
  driveFileId: j.driveFileId || null,
  ok: true
};

const p = $("02 Validate Parameters").item.json;
const headline = p.headline || "Featured Image";
const subheadline = p.subheadline || "";

// Generate real SVG image binary data with programmatic typography and safe area margins
const svgWidth = 1200;
const svgHeight = 630;
const svgContent = `<svg xmlns="http://www.w3.org/2000/svg" width="${svgWidth}" height="${svgHeight}" viewBox="0 0 ${svgWidth} ${svgHeight}">
  <rect width="100%" height="100%" fill="#1e293b"/>
  <rect x="40" y="40" width="1120" height="550" fill="none" stroke="#3b82f6" stroke-width="4" rx="16"/>
  <text x="80" y="260" fill="#ffffff" font-family="sans-serif" font-size="48" font-weight="bold">${headline.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</text>
  <text x="80" y="340" fill="#94a3b8" font-family="sans-serif" font-size="28">${subheadline.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</text>
  <text x="1080" y="100" fill="#3b82f6" font-family="sans-serif" font-size="24" font-weight="bold" text-anchor="end">Mohamed Arslan</text>
</svg>`;

const binaryBuffer = Buffer.from(svgContent, "utf-8");
const base64Data = binaryBuffer.toString("base64");

return {
  json: {
    jobId: p.jobId,
    assetKey: "featured-main",
    assetType: "featured_image",
    generatorMode: p.mode,
    width: svgWidth,
    height: svgHeight,
    fileSizeBytes: binaryBuffer.length,
    mimeType: "image/svg+xml",
    ok: true
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: "image/svg+xml",
      fileName: "featured-main.svg",
      fileExtension: "svg",
      fileSize: `${binaryBuffer.length} B`
    }
  }
};

const item = $input.item;
const meta = item.json || {};
const hasBinary = item.binary && item.binary.data && item.binary.data.data;

if (!hasBinary) {
  return {
    success: false,
    jobId: meta.jobId || null,
    status: "FAILED",
    message: "Featured image generation failed — no binary image output produced.",
    data: null,
    warnings: [],
    errors: [{ code: "RENDER_FAILED", language: null, path: null, message: "Image renderer did not produce binary output data." }],
    nextAllowedActions: ["retry", "cancel"]
  };
}

return {
  success: true,
  jobId: meta.jobId,
  status: "ASSETS_READY",
  message: "Featured image binary generated successfully.",
  data: {
    assetKey: meta.assetKey,
    assetType: meta.assetType,
    width: meta.width,
    height: meta.height,
    fileSizeBytes: meta.fileSizeBytes,
    mimeType: meta.mimeType
  },
  warnings: [],
  errors: [],
  nextAllowedActions: ["optimize_images"]
};

const j = $json || {};
const code = j.errorCode || "INVALID_INPUT";
const message = j.errorMessage || "Invalid input parameters for featured image generator.";
return {
  success: false,
  jobId: j.jobId || null,
  status: "FAILED",
  message,
  data: null,
  warnings: [],
  errors: [{ code, language: null, path: null, message }],
  nextAllowedActions: ["cancel"]
};
